const rows = [
  { 分類: "飲料", 品項: "美式咖啡", 金額: 120 },
  { 分類: "飲料", 品項: "拿鐵", 金額: 150 },
  { 分類: "點心", 品項: "可頌", 金額: 80 },
  { 分類: "點心", 品項: "司康", 金額: 90 },
  { 分類: "飲料", 品項: "紅茶", 金額: 60 },
];
const byCategory = {};
for (const r of rows) {
  byCategory[r.分類] = byCategory[r.分類] ?? { 筆數: 0, 小計: 0 };
  byCategory[r.分類].筆數 += 1;
  byCategory[r.分類].小計 += r.金額;
}
const lines = Object.entries(byCategory).map(([名稱, v]) => `- ${名稱}：${v.筆數} 筆，共 ${v.小計} 元`);
const total = rows.reduce((sum, r) => sum + r.金額, 0);
return { ...ctx.input, 分類統計: lines.join("\n"), 總金額: total, 筆數: rows.length };
